def update(l, r, v):
    L = l + N0; R = r + N0
    while L < R:
        if R & 1:
            R -= 1
            data[R-1] = min(v,data[R-1])

        if L & 1:
            data[L-1] = min(v,data[L-1])
            L += 1
        L >>= 1; R >>= 1
# a_iの現在の値を取得
def _query(k):
    k += N0-1
    s = INF
    while k >= 0:
        if data[k]:
            s = min(s, data[k])
        k = (k - 1) // 2
    return s
