class Solution:
    def maxArea(self, h: int, w: int, horizontalCuts: List[int], verticalCuts: List[int]) -> int:
        mod = int(1e9)+7
        return ( ( self.getMax(horizontalCuts, h) % mod ) * ( self.getMax(verticalCuts, w) % mod ) ) % mod

    def getMax(self, cuts, size):
        if len(cuts) == 1:
            return max(cuts[0], size - cuts[0])

        cuts.sort()

        max_cut_size = max(cuts[0], size - cuts[-1])
        for index in range(1, len(cuts)):
            if cuts[index] - cuts[index - 1] > max_cut_size:
                max_cut_size = cuts[index] - cuts[index - 1]

        return max_cut_size

def nck(n, k, cache = {}):
    if k > n or k < 0: return 0
    if k == 0 or k == n: return 1
    if k*2 > n: k = n-k
    if (n, k) in cache: return cache[(n, k)]

    z = cache[(n, k)] = nck(n-1, k-1) + nck(n-1, k)
    return z

def bits(n):
    b = 0
    while n:
        if n&1: b += 1
        n >>= 1
    return b

def count(n, k):
    z, b, c = 0, 63, 0
    for b in reversed(range(64)):
        if (n>>b)&1:
            z += nck(b, k-c)
            c += 1
        if not k: break
    return z + (bits(n) == k)

