class Solution(object):
     def findSubstring(self, s, words):
         """
         :type s: str
         :type words: List[str]
         :rtype: List[int]
         """
         if not s or words==[]:
             return []
         lenstr=len(s)
         lenword=len(words[0])
         lensubstr=len(words)*lenword
         times={}
         for word in words:
             if word in times:
                 times[word]+=1
             else:
                 times[word]=1
         ans=[]
         for i in range(min(lenword,lenstr-lensubstr+1)):
             self.findAnswer(i,lenstr,lenword,lensubstr,s,times,ans)
         return ans
     def findAnswer(self,strstart,lenstr,lenword,lensubstr,s,times,ans):
         wordstart=strstart
         curr={}
         while strstart+lensubstr<=lenstr:
             word=s[wordstart:wordstart+lenword]
             wordstart+=lenword
             if word not in times:
                 strstart=wordstart
                 curr.clear()
             else:
                 if word in curr:
                     curr[word]+=1
                 else:
                     curr[word]=1
                 while curr[word]>times[word]:
                     curr[s[strstart:strstart+lenword]]-=1
                     strstart+=lenword
                 if wordstart-strstart==lensubstr:
                     ans.append(strstart)

def sort_csv_columns(csv_file_content, sep=';', end='\n'):
    '''Sort a CSV file by column name.'''
    csv_columns = zip(*(row.split(sep) for row in csv_file_content.split(end)))
