def solve(a, b , c):
	ans = 0
	if len(b) == 1:
		for token in a:
			if c(token, b[0]):
				ans += token[0] - b[0][0] + 1
		return ans

	if len(b) == 2:
		for i in range(len(a) - 1):
			if c(a[i], b[0]) and c(a[i + 1], b[-1]):
				ans += 1
		return ans

	v = b[1 : -1] + [[100500, '#']] + a
	p = [0] * len(v)
	for i in range(1, len(v)):
