class Game():

    def __init__(self, n):
        k = 2 * n + 1
        self.board = {frozenset(k * r + 1 + c + d for d in (0, n, n + 1, k))
                        for r in range(n) for c in range(n)}

    def play(self, lines):
        lines = set(lines)
        while 1:
            for cell in self.board:
                stick = cell - lines
                if len(stick) <= 1:
                    lines |= stick
                    self.board.remove(cell)
                    break
            else: break
        return sorted(lines)

def roll_dice (rolls, sides, threshold):
    dp = [0] * (rolls * sides + 1)
    for i in range(1, sides+1):
        dp[i] = 1

    for _ in range(rolls-1):
        for x in range((rolls * sides), 0, -1):
            dp[x] = sum(dp[max(1, x-sides):x])

    return sum(dp[threshold:]) / sum(dp[1:])

def processes(start, end, processes):
  '''Dijkstra's shortest path algorithm'''
  q = [(start,[])]
  visited = set()

  while q:
      s, path = q.pop(0)
      if s == end: return path
      visited.add(s)
      for p in [x for x in processes if x[1] == s]:
          if not p[2] in visited:
              q.append((p[2], path + [p[0]]))
  return []

