class Solution:
    def stoneGameII(self, arr):
        a =[]
        s=0
        n = len(arr)
        for i in arr[::-1]:
            s+=i
            a.append(s)
        a=a[::-1]
        @lru_cache(None)
        def fun(i,m):
            if i+2*m>=n:return a[i]
            mn = inf
            for ii in range(1,2*m+1):
                if ii>m:
                    ans = fun(i+ii,ii)
                else:
                    ans=fun(i+ii,m)
                if ans<mn:
                    mn = ans
            return a[i]-mn
        return fun(0,1)

import sys

class Fenwick(object):
  def __init__(self, n):
    self.n = n
    self.a = [10**9 for i in range(n)]
    self.w= 10**9

  def zag(self, i, zn):
    self.w= min(self.w, zn)
    while i < self.n:
      self.a[i] = min(self.a[i], zn)
      i = (i | (i + 1))

  def pol(self, r):
    ans= 10**9
    while r >= 0:
      if ans> self.a[r]:
        ans= self.a[r]
      if ans== self.w:
        break
      r = (r & (r + 1)) - 1
    return ans

