     def decodeString(self, s):
         """
         :type s: str
         :rtype: str
         """
         stack = []
         stack.append(["", 1])
         num = ""
         for ch in s:
             if ch.isdigit():
               num += ch
             elif ch == '[':
                 stack.append(["", int(num)])
