        self.head = head
        self.tail = tail

    def to_array(self):
        return [self.head] + (self.tail.to_array() if self.tail is not None else [])

    @classmethod
    def from_array(cls, arr):
        if not arr:
            return None
        return Cons(arr.pop(0), Cons.from_array(arr) if arr else None)

