class Solution:
     def nearestPalindromic(self, num):
         """
         :type n: str
         :rtype: str
         """
         K = len(num)
         candidates = set([10**K + 1, 10**(K-1) - 1])
         Prefix = int(num[:(K+1)//2])

         for start in map(str, [Prefix-1, Prefix, Prefix+1]):
             candidates.add(start + [start, start[:-1]][K & 1][::-1])

         candidates.discard(num)

         return str(min(candidates, key=lambda x: (abs(int(x) - int(num)), int(x))))

import numpy as np


def solve(n, k):
    if k % 2 == 1:
        return 0
    k //= 2

    MOD = 10 ** 9 + 7

    dp = np.zeros((1, k + 1), dtype=np.int64)
    dp[0, 0] = 1
    for i in range(1, n + 1):
        max_d = min(i + 1, n - i + 1, k + 1)
        ndp = np.zeros((max_d, k + 1), dtype=np.int64)
        for d, ks in enumerate(dp):
            base = ks[:k - d + 1]
            if d > 0:
                ndp[d - 1, d:] += base * d ** 2
            if max_d > d:
                ndp[d, d:] += base * (2 * d + 1)
            if max_d > d + 1:
                ndp[d + 1, d:] += base
        dp = ndp % MOD

    return dp[0, k]


