def coor_neighbor(coor, dxs, dys):
    x, y = coor
    for dx in dxs:
        for dy in dys:
            yield x + dx, y + dy


def coor_bottoms(coor):
    return coor_neighbor(coor, (-1, 0, 1), (-1, ))


def coor_tops(coor):
