class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        if n<=1: 
            return 0
        l,r = n,-1

        for i in range(1,n):
            if arr[i]<arr[i-1]:
                l = i
                break
        # monotonicially increasing
        if l == n: return 0

        for j in range(n-2,-1,-1):
            if arr[j]>arr[j+1]:
                r = j
                break

        # you can delete all to the left of r (including r)
        # you can also delete all to the right of l (including l)
        ans = min(r+1,n-l)

        i = 0
        # sliding window, find the rightmost i for each j
        # note at all time i must be less than l
        for j in range(r+1,n):
            while i<l and arr[i] <= arr[j]:
                i += 1
            ans = min(ans,j-i)
        return ans

class Solution:
     def canPartition(self, nums):
         """
         :type nums: List[int]
         :rtype: bool
         """
         _sum=sum(nums)
         div,mod=divmod(_sum,2)
         if mod!=0:
             return False
         target=[div]*2
         self._len=len(nums)
         nums.sort(reverse=True)
         def dfs(index,target):
             if index==self._len:
                 return True
             num=nums[index]
             for i in range(2):
                 if target[i]>=num:
                     target[i]-=num
                     if dfs(index+1,target):return True
                     target[i]+=num
             return False
         return dfs(0,target)

