def cost_of_carpet(room_length, room_width, roll_width, roll_cost):
    x, y = sorted((room_length, room_width))
    if y == 0 or x > roll_width: return "error"
    if y < roll_width: return round(x * roll_width * roll_cost, 2)
    return round(y * roll_width * roll_cost, 2)

from math import ceil

def branch(n):
    if n == 1:
        return 0
    l = int(ceil(n ** 0.5)) // 2
    n -= (2 * l - 1) ** 2 + 1
    return n // (2*l or 1)

