def reversi_row(moves):
    row = '........'
    stones = '*O'
    for i, m in enumerate(moves):
        L, M, R = row[:m], stones[i%2], row[m+1:]
        if R!='' and R[0] == stones[(i+1)%2] and R.find(stones[i%2])>0 and '.' not in R[:R.find(stones[i%2])]:
