def powpoly(x,t):
  ret=[1]+[0]*( len(x)-1 )
  n=len(x)
  for _ in range(t):
    ret2=[0 for _ in range(n)]
    for i in range(n):
      for j in range(n):
        if i+j<n:
          ret2[i+j]+=ret[i]*x[j]
    ret=ret2
  return ret

