    ts = 3 * salads + 5 * appetizers
    return max(tp, ts)

MOVES = {"right": (0,1), "down": (1,0), "left": (0,-1), "up": (-1,0)}


def get_password(grid, dirs):
    x,y = next( (x,y) for x,r in enumerate(grid) for y,c in enumerate(r) if c=='x' )
    pwd = []
    for d in dirs:
        dx,dy = MOVES[d.strip('T')]
        x,y = x+dx,y+dy
        if d.endswith('T'): pwd.append(grid[x][y])
    return ''.join(pwd)

class Solution:
    def minFallingPathSum(self, arr: List[List[int]]) -> int:
        dp = [0] * len(arr[0])
        for r, row in enumerate(arr):
            minNb = min(dp)
            min1 = dp.index(minNb)
            dp[min1] = float('inf')
            min2 = dp.index(min(dp))
            dp[min1] = minNb

            for c in range(len(row)):
                if c != min1:
                    row[c] += dp[min1]
                else:
                    row[c] += dp[min2]
                #row[c] += min(dp[:c]+dp[c+1:])
            dp = row[:]
        return min(dp)

