class Solution:
     def searchMatrix(self, matrix, target):
         """
         :type matrix: List[List[int]]
         :type target: int
         :rtype: bool
         """
         m = len(matrix)
         if m == 0:
             return False
         n = len(matrix[0])
         if n == 0:
             return False
         row, col = 0, n-1
         while row < m and col >= 0:
             if matrix[row][col] == target:
                 return True
             elif matrix[row][col] > target:
                 col -= 1
             else:
                 row += 1
         return False

