def full_way(u):
    res = set()

    while u >= 1:
        res.add(u)
        u //= 2

    return res


def get_way(u, v):
    res1 = full_way(u)
    res2 = full_way(v)

    m = max(res1 & res2)

    res = set()
    for x in res1 | res2:
        if x > m:
            res.add(x)

    return res


