from functools import lru_cache

def failure(pat):
    i, target, n = 1, 0, len(pat)
    res = [0]
    while i < n:
        if pat[i] == pat[target]:
            target += 1
            res.append(target)
            i+=1
        elif target:
            target = res[target-1]
        else:
            res.append(0)
            i += 1
    return res


class Solution:
    def findGoodStrings(self, n: int, s1: str, s2: str, evil: str) -> int:
        f = failure(evil)
        @lru_cache(None)
        def dfs(idx, max_matched=0, lb=True, rb=True):

            if max_matched == len(evil): return 0
            if idx == n: return 1

            l = s1[idx] if lb else 'a'
            r = s2[idx] if rb else 'z'

            candidates = [chr(i) for i in range(ord(l), ord(r) + 1)]

            res = 0
            for i, c in enumerate(candidates):
                next_matched = max_matched
                while next_matched and evil[next_matched]!= c:
                    next_matched = f[next_matched-1]
                res += dfs(idx+1, next_matched + (evil[next_matched] == c), 
                          (lb and i==0), (rb and i == (len(candidates) - 1)))
            return res

        return dfs(0) % (10**9 + 7)

class Solution:
    def minFallingPathSum(self, A: List[List[int]]) -> int:
        dp = [A[0][:], [0 for _ in A[0]]]
        for i in range(1, len(A)):
            for j in range(len(A[i])):
                dp[i & 1][j] = min([dp[(i - 1) & 1][j + k] for k in (-1, 0, 1) if 0 <= j + k < len(A[i])]) + A[i][j]
        return min(dp[(len(A) - 1) & 1])

def bowling_score(rolls):
  "Compute the total score for a player's game of bowling."

  def is_spare(rolls):
    return 10 == sum(rolls[:2])

  def is_strike(rolls):
    return 10 == rolls[0]

  def calc_score(rolls, frame):
    return (sum(rolls) if frame == 10 else
            sum(rolls[:3]) + calc_score(rolls[1:], frame+1) if is_strike(rolls) else
            sum(rolls[:3]) + calc_score(rolls[2:], frame+1) if is_spare(rolls) else
            sum(rolls[:2]) + calc_score(rolls[2:], frame+1))

  return calc_score(rolls,1)

