def stats_disc_distr(distrib):
    err = check_errors(distrib)
    if not err:
        mean = sum(x[0] * x[1] for x in distrib)
        var = sum((x[0] - mean) ** 2 * x[1] for x in distrib)
        std_dev = var ** 0.5
    return [mean, var, std_dev] if not err else err

def check_errors(distrib):
