class Solution:
     def checkSubarraySum(self, nums, k):
         """
         :type nums: List[int]
         :type k: int
         :rtype: bool
         """
         if k==0:
             j=0
             for i in range(0,len(nums)):
                 if nums[i]==0:
                     if j<i:
                         return True
                 else:
                     j=i+1
             return False
         dic={0:-1}
         c=0
         for i in range(0,len(nums)):
             c=(c+nums[i])%k
             if c in dic:
                 if i-dic[c]>1:
                     return True
             else:
                 dic[c]=i
         return False

def combos(n, m = 1):
    if n < m:return []
    res = [[n]]
    for i in xrange(m, n):
        l = [i]
        for j in combos(n - i, i):
           res += [l + j]
    return res

class Solution:
     def permute(self, nums):
         """
         :type nums: List[int]
         :rtype: List[List[int]]
         """
         all_permutes = []
         self.permute_nums(all_permutes, nums, [])
         return all_permutes

     def permute_nums(self, all_permutes, nums, cur_permute):
         if len(nums) == 0:
             all_permutes.append(cur_permute)
             return

         for i in range(len(nums)):
             num = nums[i]

             self.permute_nums(all_permutes, nums[0:i] + nums[i+1:len(nums)], cur_permute + [num])

from functools import lru_cache


def optimal_number_of_coins(n, coins):
    @lru_cache(maxsize=None)
    def f(amount: int, idx: int) -> float:
        q, r = divmod(amount, coins[idx])
        if r == 0:
            return q
        elif amount < 0 or idx <= 0:
            return float("inf")
        else:
            return min(1 + f(amount - coins[idx], idx), f(amount, idx - 1))

    coins = sorted(set(coins))
    return f(n, len(coins) - 1)

