import math
def nth_perm(n,d):
    digits = [str(i) for i in range(d)]
    out = ''
    for i in range(1, d):
        cycles = math.ceil(n/math.factorial(d-i))
        out += digits.pop((cycles % (d-i+1)) - 1)
    return out + digits.pop()

class BIT():
    def __init__(self,n):
        self.BIT=[0]*(n+1)
        self.num=n

    def query(self,idx):
        res_sum = 0
        while idx > 0:
            res_sum += self.BIT[idx]
            idx -= idx&(-idx)
        return res_sum

    #Ai += x O(logN)
    def update(self,idx,x):
        while idx <= self.num:
            self.BIT[idx] += x
            idx += idx&(-idx)
        return

