def chain_arith_deriv(n, k):
    if len(prime_factors(n)) < 2:
        return "{} is a prime number".format(n)
    chain = [n]
    while k > 1:
        k, n = k-1, arith_deriv(n)
        chain.append(n)
    return chain


def arith_deriv(n):
    factors = prime_factors(n)
    return sum(n * factors.count(factor) // factor for factor in set(factors)) or 1


def prime_factors(n):
    if n < 2:
        return []
    factors = []
    for k in (2, 3):
        while n % k == 0:
            n //= k
            factors.append(k)
    k = 5
    step = 2
    while k * k <= n:
        if n % k:
            k += step
            step = 6 - step
        else:
            n //= k
            factors.append(k)
    if n > 1:
        factors.append(n)
    return factors

class Solution:
     def shoppingOffers(self, price, special, needs):
         """
         :type price: List[int]
         :type special: List[List[int]]
         :type needs: List[int]
         :rtype: int
         """
         def dfs(curr, special, needs):
             p=curr+sum(p*needs[i] for i,p in enumerate(price))
             for si in range(len(special)):
                 s = special[si]
                 if all(n>=s[i] for i,n in enumerate(needs)):
                     p=min(p, dfs(curr+s[-1], special[si:], [n-s[i] for i,n in enumerate(needs)]))
                 # else: p=min(p, dfs(curr, special[si+1:], needs))
             return p
         return dfs(0, special, needs)

