def missing(seq):
    for digits in range(1, len(seq) // 2 + 1):
        my_seq = last = seq[:digits]
        n = int(my_seq)
        missing = None

        while len(my_seq) < len(seq):
            n += 1
            my_seq += str(n)

            if not seq.startswith(my_seq):
                if missing == None:
                    missing = n
                    my_seq = last
                else:
                    break
            else:
                last = my_seq

        if my_seq == seq and missing:
            return missing

    return -1

def decodeBits(bits):
    import re

    # remove trailing and leading 0's
    bits = bits.strip('0')

    # find the least amount of occurrences of either a 0 or 1, and that is the time hop
    time_unit = min(len(m) for m in re.findall(r'1+|0+', bits))

    # hop through the bits and translate to morse
    return bits[::time_unit].replace('111', '-').replace('1','.').replace('0000000','   ').replace('000',' ').replace('0','')

