class Solution:
    def minIncrementForUnique(self, A: List[int]) -> int:
        if not A:
            return 0

        A.sort()
        prev = A[0]
        res = 0
        for num in A[1:]:
            if num <= prev:
                prev += 1
                res += prev-num

            else:
                prev = num

        return res

class Solution:
     def findLHS(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         count = collections.Counter(nums)
         ret = 0
         for i in count:
             if i+1 in count:
                 ret = max(ret, count[i]+count[i+1])

         return ret

