def valid(step):
    cycle = step // n
    rem = step % n
    x = x1
    y = y1
    x += psx[n-1] * cycle
    y += psy[n-1] * cycle
    if rem > 0:
        x += psx[rem-1]
        y += psy[rem-1]
    ManhattanDistance = abs(x - x2) + abs(y - y2)
    return (ManhattanDistance <= step)

def binsearch(top, bot):
    res = -1
    while top <= bot:
        mid = (top + bot) // 2
        if valid(mid):
            res = mid
            bot = mid - 1
        else:
            top = mid + 1
    return res


