def getyx(h, w, tot, cnt):
    b = (w - 1) * .5
    c = h * (tot - h * (w * w - 2 * w * (1 - h) - 1) * .25)
    for y in range((h + 3) // 2):
        d = (c - h * y * (w * y - h * w + w))
        if d >= 0:
            x = b - sqrt(d) / h
            if x.is_integer() and x >= 0.:
                check(h, w, y, int(x), cnt.copy())


