                len_v = max_child[v][0] + 1
                if len_v > chlen[0]:
                    chlen[1] = chlen[0]
                    chlen[0] = len_v
                elif len_v > chlen[1]:
                    chlen[1] = len_v
            for v in adj[u]:
                if v == p:
                    continue
                stack.append(
                    (v, u, chlen[int(max_child[v][0] + 1 == chlen[0])]))
        else:
            is_body = (u == b)
            if not is_body:
                for v in adj[u]:
                    if v != p and ret[v]:
                        is_body = True
                        break
            if is_body:
                body.append(u)
            ret[u] = is_body
    del ret
    # end of dfs2
    ok = False
    body_len = len(body)
    can_turn = [False] * n
    for i in range(n):
        if 3 <= sum(1 for l in max_child[i] + [max_parent[i]] if l >= body_len):
            can_turn[i] = True
            ok = True
    if not ok:
        print("NO")
