class Solution:
     def largestNumber(self, nums):
         """
         :type nums: List[int]
         :rtype: str
         """
         nums = [str(n) for n in nums]

         nums.sort(reverse=True)

         for i in range(1, len(nums)):
             if len(nums[i-1]) > len(nums[i]):
                 ran = len(nums[i])
                 j = i
                 while j-1 >= 0 and nums[j-1][:ran] == nums[j] and nums[j-1]+nums[j]<=nums[j]+nums[j-1]:
                     nums[j-1], nums[j] = nums[j], nums[j-1]
                     j -= 1

         return str(int(''.join(nums)))

class Solution:
    def move(self, pos, direction):
        x, y = pos
        if direction == 0:
            y += 1
        elif direction == 1:
            x += 1
        elif direction == 2:
            y -= 1
        elif direction == 3:
            x -= 1
        return (x, y)

    def isRobotBounded(self, instructions: str) -> bool:
        direction = 0 # 0 for north, 1 for east, 2 for south, 3 for west
        pos = (0, 0)
        for i in instructions:
            if i == 'G':
                pos = self.move(pos, direction)
            elif i == 'L':
                direction = (direction - 1) % 4
            elif i == 'R':
                direction = (direction + 1) % 4
        if pos == (0, 0) or direction != 0:
            return True
        else:
            return False

