class Solution:
     def canPartitionKSubsets(self, nums, k):
         """
         :type nums: List[int]
         :type k: int
         :rtype: bool
         """
         target,rem=divmod(sum(nums),k)
         if rem or max(nums)>target: return False
         n=len(nums)
         seen=[0]*n
         nums.sort(reverse=True)

         def dfs(k,index,current_sum):
             if k==1:
                 return True

             if current_sum==target:
                 return dfs(k-1,0,0)
             for i in range(index,n):
                 if not seen[i] and current_sum+nums[i]<=target:
                     seen[i]=1
                     if dfs(k,i+1,current_sum+nums[i]):
                         return True
                     seen[i]=0
             return False

         return dfs(k,0,0)

class Solution:
    def numTriplets(self, nums1: List[int], nums2: List[int]) -> int:

        def triplets(nums1, nums2):
            sq = collections.Counter(x * x for x in nums1)
            num = collections.Counter(nums2)

            res = 0
            keys = sorted(num.keys())
            for j, x in enumerate(keys):
                if num[x] > 1 and x * x in sq:
                    res += num[x] * (num[x] - 1) // 2 * sq[x * x]
                for y in keys[j+1:]:
                    if x * y in sq:
                        res += num[x] * num[y] * sq[x * y]
            return res

        return triplets(nums1, nums2) + triplets(nums2, nums1)

