def simplify(n): 
    output = []
    exp = 0

    while n:
        n, r = divmod(n, 10)
        if r:
            output.append(f"{r}*{10**exp}" if exp else f"{r}")
        exp += 1

    return "+".join(output[::-1])

def even_fib(m):
    x,y = 0, 1
    counter = 0
    while y < m:
        if y % 2 == 0:
            counter += y
        x,y = y, x+ y
    return counter

