from math import comb


class Solution:
    def getProbability(self, balls: List[int]) -> float:
        n = len(balls)
        s = sum(balls)
        s2 = s // 2

        @lru_cache(None)
        def count(index, delta, ca):
            if index == n: return 1 if delta == 0 and ca == s2 else 0
            total = sum([count(index + 1, delta, ca + x) * comb(balls[index], x) for x in range(1, balls[index])])
            total += count(index + 1, delta + 1, ca)
            total += count(index + 1, delta - 1, ca + balls[index])
            return total

        return count(0, 0, 0) / comb(s, s // 2)

class Solution:

     def findFrequentTreeSum(self, root):
         self.sums = []
         if not root:
             return []
         self.traverse(root)
         res = collections.Counter(self.sums)
         frequent = max(res.values())
         return [x for x in res if res[x] == frequent]


     def traverse(self, root):
         if not root:
             return 0

         self_sum = root.val + self.traverse(root.left) + self.traverse(root.right)

         self.sums.append(self_sum)
         return self_sum

