def get_factors(n):
    factors = []
    for p in PRIMES:
        if p > n: break
        while n % p == 0:
            factors.append(p)
            n //= p
    if n > 1:
        factors.append(n)
    return Counter(factors)


def mul_power(n, k):
    factors, lcm = get_factors(n), 1
    for p, e in factors.items():
        lcm *= p**(ceil(e/k)*k)
    return lcm // n

