def fact(n):
    res = 1
    for i in range(1,n+1):
        res *= i
    return res

def f(n):
    l = fact(n) * n
    ans = l * (l-n+2) // 2
    for i in range(1,n):
        ans -= fact(n) // fact(i+1) * n * (i * (n-i) - 1)
    return ans

