class Solution:
    def displayTable(self, orders: List[List[str]]) -> List[List[str]]:
        answer = []

        if orders is None or len(orders) == 0 or len(orders[0]) == 0:
            return answer

        items = set()

        for order in orders:
            items.add(order[2])

        items = sorted(list(items))
        answer.append([\"Table\"])

        for item in items:
            answer[0].append(item)

        hashMap = collections.defaultdict(list)
        itemIndex = self.convertItemToIndex(answer[0])
        m = len(answer[0])

        for order in orders:
            hashMap[int(order[1])].append(order[2])

        hashMap = {key : hashMap[key] for key in sorted(hashMap.keys())}
        currentIndex = 1

        for key in hashMap.keys():
            answer.append([\"0\"] * m)
            answer[currentIndex][0] = str(key)
            countMap = defaultdict(lambda: 0)

            for currentItem in hashMap[key]:
                countMap[currentItem] += 1

            for currentItem in countMap.keys():
                answer[currentIndex][itemIndex[currentItem]] = str(countMap[currentItem])

            currentIndex += 1

        return answer

    def convertItemToIndex(self, tempAns):
        itemToIndex = {}

        for i, curr in enumerate(tempAns):
            itemToIndex[curr] = i

        return itemToIndex

# This is the Miller-Rabin test for primes, which works for super large n

import random

def even_odd(n):
    s, d = 0, n
    while d % 2 == 0:
          s += 1
          d >>= 1
    return s, d

def Miller_Rabin(a, p):
    s, d = even_odd(p-1)
    a = pow(a, d, p)
    if a == 1: return True
    for i in range(s):
        if a == p-1: return True
        a = pow(a, 2, p)
    return False

def is_prime(p):
    if p == 2: return True
    if p <= 1 or p % 2 == 0: return False
    return all(Miller_Rabin(random.randint(2,p-1),p) for _ in range(40))

