        keep_casing = lambda m: n.upper() if m.group().isupper() else n
        text = re.sub(b, keep_casing, text, flags=re.I)
    if not text: return ''
    if text[0] in 'hH': text = text.upper()
    if text[0] in 'wW': text = 'LOL ' + text
    if len(re.sub('[!?]', '', text)) >= 32: text = re.sub('\A(LOL |)', r'\1OMG ', text)
