# Function to calculate order of the number
def order(x):
	# Variable to store of the number
	n = 0
	while (x != 0):
		n = n + 1
		x = x // 10

	return n


# Function to check whether the given
# number is Armstrong number or not
def isArmstrong(x):
	n = order(x)
	temp = x
	sum1 = 0

	while (temp != 0):
		r = temp % 10
		sum1 = sum1 + power(r, n)
		temp = temp // 10

	# If condition satisfies
	return (sum1 == x)


